const fila = $('Lead en curso').first().json;
const opp = ($input.first().json.data || {}).opportunity || {};
const ETAPAS = {
  "Lead Nuevo": "cf8fc770-81b1-422c-8394-d00bfb97a3f0",
  "Saludo Enviado": "f9709293-d03c-47f1-949f-0c03ab077a45",
  "Evento Identificado": "fec50c94-fba0-444b-8c75-7a97da9e0daa",
  "Productos Mostrados": "49c7401f-8af1-4d8f-a1b4-e989b6d0a5e2",
  "Cotizado": "96fa0ade-c853-4db3-97f4-56d58d69af8c",
  "Esperando Pago": "843a06f1-1214-4baa-a3a0-f197cb240b5d",
  "Pago Confirmado": "96d760e5-f290-456c-a117-57e61ce6c27d",
  "Diseño en Proceso": "d35bb30d-97d5-48c4-81f8-5ecabf32e57d",
  "En Producción": "008689c6-80d8-4712-981b-1d800e1e6137",
  "Enviado": "218b9b41-4007-4b1c-bbe4-4e775ddf00b5",
  "En Espera": "48de80e9-31a9-472a-b030-5b9fe9174810",
  "Ganado": "909a816d-997e-4d90-8dc1-dc4b0dcd16d7",
  "Ventas Perdidas": "6abfe419-adf2-4df5-87c5-ef4f62e01464"
};
const nombreDe = Object.fromEntries(Object.entries(ETAPAS).map(([k, v]) => [v, k]));
const etapaActual = nombreDe[opp.pipelineStageId] || null;

const cfg = CAMPANIAS[fila.campania];
const ahora = Date.now();
const t = x => (x ? new Date(x).getTime() : 0);

function salida(o) { return [{ json: { ...fila, etapa_actual: etapaActual, ...o } }]; }

// ── Cortes que ganan sobre todo lo demás ────────────────────────────────────────
if (!cfg) return salida({ accion: 'cerrar', motivo: 'sin_campania' });

// Etapas donde el agente no habla: no se re-engancha a alguien que está con una
// persona, pagando o en producción. Va ANTES del chequeo de "cambió la etapa" porque
// es el motivo más informativo de los dos: ambos cortan, pero éste dice por qué.
const MUDAS = ['En Espera', 'Pago Confirmado', 'En Producción', 'Diseño en Proceso',
               'Enviado', 'Ganado', 'Ventas Perdidas'];
if (MUDAS.includes(etapaActual)) {
  return salida({ accion: 'cerrar', motivo: 'bloqueado' });
}

// La etapa se movió: la campaña dejó de tener sentido. Réplica de los Get_Entity*+If.
if (etapaActual !== fila.etapa_al_armar) {
  return salida({ accion: 'cerrar', motivo: 'etapa_cambio' });
}

// ── ¿Toca evaluar el cierre? ────────────────────────────────────────────────────
// Va ANTES del corte por respuesta a propósito. En el origen el `Wait3` de 24 h se
// cumple aunque el lead haya escrito, y justamente ahí es donde corre el clasificador
// de desinterés: "respondió" no es motivo para cerrar en silencio, es la ENTRADA de la
// decisión. Poniéndolo después, el clasificador no corría nunca.
const vencidaEval = fila.evaluacion_at && t(fila.evaluacion_at) <= ahora;
if (vencidaEval) {
  const hablo = t(fila.ultimo_inbound_at) > t(fila.evaluacion_desde_at || fila.desde_at);
  if (!hablo) return salida({ accion: 'cerrar', motivo: 'silencio',
                              efecto: cfg.silencio });
  return salida({ accion: 'clasificar' });
}

// El lead respondió después de que se armó la campaña: no se le manda ninguna ola más.
// El caso normal ni llega acá — cuando el lead escribe, W1 REESCRIBE la fila con una
// campaña nueva y la vieja desaparece. Esto es la red por si esa escritura no ocurre
// (por ejemplo un turno que murió después de `Evidencia del turno`).
if (t(fila.ultimo_inbound_at) > t(fila.desde_at)) {
  return salida({ accion: 'cerrar', motivo: 'respondio' });
}

// ── ¿Toca mandar una ola? ───────────────────────────────────────────────────────
const vencidoToque = fila.proximo_at && t(fila.proximo_at) <= ahora;
if (vencidoToque && fila.ola < cfg.olas.length) {
  const i = fila.ola;                       // 0-based: la ola que toca mandar
  const [id, bot, verificado, txt] = TEXTOS[fila.campania][i];
  const texto = txt.replace('{evento}', fila.evento || 'tu evento');
  const esUltima = (i + 1) >= cfg.olas.length;

  // El siguiente toque se agenda desde que se armó la campaña, no desde ahora: así un
  // cron que corre tarde no corre toda la cadencia hacia adelante.
  const base = t(fila.desde_at);
  const prox = esUltima ? null
    : new Date(base + cfg.olas[i + 1] * 60000).toISOString();
  const evalAt = esUltima
    ? new Date(ahora + cfg.eval_h * 3600000).toISOString() : null;

  return salida({ accion: 'toque', ola_nueva: i + 1, texto, texto_id: id,
                  bot_kommo: bot, texto_verificado: verificado,
                  proximo_at_nuevo: prox, evaluacion_at_nueva: evalAt,
                  evaluacion_desde_at_nueva: esUltima ? new Date(ahora).toISOString() : null });
}

// ── ¿Toca evaluar el cierre? ────────────────────────────────────────────────────
if (vencidaEval) {
  // Silencio: el lead no escribió desde que arrancó la ventana de evaluación.
  const hablo = t(fila.ultimo_inbound_at) > t(fila.evaluacion_desde_at || fila.desde_at);
  if (!hablo) return salida({ accion: 'cerrar', motivo: 'silencio',
                              efecto: cfg.silencio });
  // Habló: hay que clasificar si fue desinterés. Lo decide el LLM, como el origen.
  return salida({ accion: 'clasificar' });
}

// Nada que hacer todavía: se suelta el lock y se deja como estaba.
return salida({ accion: 'nada' });

const CAMPANIAS = {
  "rebeca": {
    "etapa": "Saludo Enviado",
    "olas": [
      60,
      240,
      300
    ],
    "eval_h": 24,
    "silencio": {
      "etapa": "Ventas Perdidas"
    },
    "desinteres": {
      "etapa": "Ventas Perdidas"
    },
    "interes": null
  },
  "imagen": {
    "etapa": "Evento Identificado",
    "olas": [
      60,
      240,
      300
    ],
    "eval_h": 24,
    "silencio": {
      "etapa": "Ventas Perdidas"
    },
    "desinteres": {
      "etapa": "Ventas Perdidas"
    },
    "interes": null
  },
  "cotizacion": {
    "etapa": "Productos Mostrados",
    "olas": [
      60,
      240,
      300
    ],
    "eval_h": 24,
    "silencio": {
      "tag": "r1_sin_informacion"
    },
    "desinteres": {
      "etapa": "Ventas Perdidas"
    },
    "interes": {
      "tag": "r1_sin_informacion"
    }
  },
  "7pasos": {
    "etapa": "Cotizado",
    "olas": [],
    "eval_h": 24,
    "silencio": {
      "tag": "r1_con_informacion"
    },
    "desinteres": {
      "etapa": "Ventas Perdidas"
    },
    "interes": {
      "tag": "r1_con_informacion"
    }
  }
};
const d = $('Decidir acción').first().json;
const cfg = CAMPANIAS[d.campania] || {};

let efecto = d.efecto || null;
let motivo = d.motivo || 'cerrado';

// Viene del clasificador de desinterés (réplica de `Message a model` + If4 del origen).
if (d.accion === 'clasificar') {
  const c = $input.first().json || {};
  const crudo = String(c.message?.content ?? c.content ?? c.text ?? '').trim();
  // El prompt del origen contesta "Si" / "No". Cualquier otra cosa se trata como
  // desinterés, que es lo que hace su `If4` (compara contra "No"; si no matchea, pierde).
  const desinteres = !/^no\b/i.test(crudo);
  efecto = desinteres ? cfg.desinteres : cfg.interes;
  motivo = desinteres ? 'desinteres' : 'sin_desinteres';
}

return [{ json: { ...d, motivo, efecto,
                  mover_etapa: !!(efecto && efecto.etapa),
                  etapa_destino: (efecto && efecto.etapa) || null,
                  tag: (efecto && efecto.tag) || null } }];
